ALTER TABLE "payment" ALTER COLUMN "paid_at" SET DATA TYPE timestamp;--> statement-breakpoint
ALTER TABLE "payment" ALTER COLUMN "created_at" SET DATA TYPE timestamp;--> statement-breakpoint
